-- Phase 4: Career Engine - Advanced MLM Functions\n-- This script adds advanced functions for career progression and reporting\n\n-- Function: Calculate team size recursively\nCREATE OR REPLACE FUNCTION calculate_team_size(user_id UUID)\nRETURNS INTEGER AS $$\nWITH RECURSIVE team_tree AS (\n  -- Base case: direct referrals\n  SELECT referrer_id\n  FROM referrals\n  WHERE sponsor_id = user_id AND verified = TRUE\n\n  UNION ALL\n\n  -- Recursive case: indirect referrals\n  SELECT r.referrer_id\n  FROM referrals r\n  INNER JOIN team_tree tt ON r.sponsor_id = tt.referrer_id\n  WHERE r.verified = TRUE\n)\nSELECT COUNT(*)::INTEGER FROM team_tree;\n$$ LANGUAGE SQL STABLE;\n\n-- Function: Get team structure for reporting\nCREATE OR REPLACE FUNCTION get_team_structure(user_id UUID)\nRETURNS TABLE (\n  level INTEGER,\n  count BIGINT,\n  total_points BIGINT,\n  avg_grade TEXT\n) AS $$\nWITH RECURSIVE team_tree AS (\n  SELECT referrer_id, 0 AS level\n  FROM referrals\n  WHERE sponsor_id = user_id AND verified = TRUE\n\n  UNION ALL\n\n  SELECT r.referrer_id, tt.level + 1\n  FROM referrals r\n  INNER JOIN team_tree tt ON r.sponsor_id = tt.referrer_id\n  WHERE r.verified = TRUE AND tt.level < 5\n)\nSELECT\n  tt.level,\n  COUNT(*)::BIGINT,\n  COALESCE(SUM(p.points), 0)::BIGINT,\n  COALESCE(ARRAY_AGG(p.current_grade ORDER BY p.current_grade)::TEXT[],\n            ARRAY[]::TEXT[])[1]::TEXT\nFROM team_tree tt\nLEFT JOIN profiles p ON tt.referrer_id = p.id\nGROUP BY tt.level\nORDER BY tt.level;\n$$ LANGUAGE SQL STABLE;\n\n-- Function: Calculate potential earnings\nCREATE OR REPLACE FUNCTION calculate_potential_earnings(user_id UUID)\nRETURNS TABLE (\n  current_monthly DECIMAL,\n  potential_next_grade DECIMAL,\n  potential_max DECIMAL\n) AS $$\nWITH user_data AS (\n  SELECT\n    p.id,\n    p.current_grade,\n    COALESCE(SUM(t.amount), 0) as current_monthly,\n    COUNT(r.id) as direct_referrals\n  FROM profiles p\n  LEFT JOIN transactions t ON p.id = t.user_id\n    AND t.type = 'commission'\n    AND t.created_at >= DATE_TRUNC('month', NOW())\n  LEFT JOIN referrals r ON p.id = r.sponsor_id AND r.verified = TRUE\n  WHERE p.id = user_id\n  GROUP BY p.id, p.current_grade\n)\nSELECT\n  current_monthly::DECIMAL,\n  (current_monthly * 1.5)::DECIMAL as potential_next_grade,\n  (current_monthly * 3)::DECIMAL as potential_max\nFROM user_data;\n$$ LANGUAGE SQL STABLE;\n\n-- Function: Get leaderboard for a specific grade\nCREATE OR REPLACE FUNCTION get_grade_leaderboard(grade_name VARCHAR, limit_count INTEGER = 100)\nRETURNS TABLE (\n  rank BIGINT,\n  user_id UUID,\n  full_name TEXT,\n  points INTEGER,\n  monthly_earnings DECIMAL,\n  team_size INTEGER\n) AS $$\nSELECT\n  ROW_NUMBER() OVER (ORDER BY COALESCE(SUM(t.amount), 0) DESC),\n  p.id,\n  CONCAT(p.first_name, ' ', p.last_name),\n  p.points,\n  COALESCE(SUM(t.amount), 0)::DECIMAL,\n  calculate_team_size(p.id)\nFROM profiles p\nLEFT JOIN transactions t ON p.id = t.user_id\n  AND t.type = 'commission'\n  AND t.created_at >= DATE_TRUNC('month', NOW())\nWHERE p.current_grade = grade_name\nGROUP BY p.id, p.first_name, p.last_name, p.points\nORDER BY SUM(t.amount) DESC\nLIMIT limit_count;\n$$ LANGUAGE SQL STABLE;\n\n-- Function: Get performance report for user\nCREATE OR REPLACE FUNCTION get_performance_report(user_id UUID)\nRETURNS TABLE (\n  metric_name TEXT,\n  value TEXT,\n  trend TEXT\n) AS $$\nWITH this_month AS (\n  SELECT\n    COUNT(r.id) as new_referrals,\n    COALESCE(SUM(t.amount), 0) as monthly_commission,\n    MAX(p.points) as total_points\n  FROM profiles p\n  LEFT JOIN referrals r ON p.id = r.sponsor_id\n    AND r.created_at >= DATE_TRUNC('month', NOW())\n  LEFT JOIN transactions t ON p.id = t.user_id\n    AND t.created_at >= DATE_TRUNC('month', NOW())\n  WHERE p.id = user_id\n),\nlast_month AS (\n  SELECT\n    COUNT(r.id) as new_referrals,\n    COALESCE(SUM(t.amount), 0) as monthly_commission\n  FROM referrals r\n  LEFT JOIN transactions t ON r.sponsor_id = t.user_id\n    AND t.created_at >= DATE_TRUNC('month', NOW() - INTERVAL '1 month')\n    AND t.created_at < DATE_TRUNC('month', NOW())\n  WHERE r.sponsor_id = user_id\n)\nSELECT\n  'Nouveaux Parrainages (ce mois)' as metric_name,\n  tm.new_referrals::TEXT,\n  CASE\n    WHEN tm.new_referrals > lm.new_referrals THEN '↑ En hausse'\n    WHEN tm.new_referrals < lm.new_referrals THEN '↓ En baisse'\n    ELSE '= Stable'\n  END\nFROM this_month tm, last_month lm\n\nUNION ALL\n\nSELECT\n  'Commission du mois',\n  tm.monthly_commission::TEXT,\n  CASE\n    WHEN tm.monthly_commission > lm.monthly_commission THEN '↑ En hausse'\n    WHEN tm.monthly_commission < lm.monthly_commission THEN '↓ En baisse'\n    ELSE '= Stable'\n  END\nFROM this_month tm, last_month lm;\n$$ LANGUAGE SQL STABLE;\n"
